INSERT INTO luma.products (id, slug, name, category_id, price_vnd, short_description, description, images, specifications, display_order, is_featured, is_published) VALUES ('p-binh-gom-luma', 'binh-gom-luma', 'Bình gốm Luma', 'gom-su', 620000, 'Một điểm nhấn nhẹ nhàng cho những góc nhà bạn yêu.', 'Dáng bình tròn mềm mại, sắc màu trung tính dễ kết hợp cùng nhiều không gian. Đặt riêng trên kệ, bên khung cửa sổ hoặc phối cùng một cành cây để tạo nên góc nhỏ của riêng bạn.', '[{"src":"/images/Gom-su/Binh-gom-Luma/binh-gom-luma.webp","thumbnail":"/images/Gom-su/Binh-gom-Luma/binh-gom-luma-600.webp","alt":"Bình gốm Luma sáng màu đặt trên tủ trong không gian có ánh sáng tự nhiên","width":1200,"height":896}]'::jsonb, '[{"label":"Chất liệu","value":null},{"label":"Kích thước","value":null},{"label":"Màu sắc","value":null}]'::jsonb, 1, true, true);
INSERT INTO luma.products (id, slug, name, category_id, price_vnd, short_description, description, images, specifications, display_order, is_featured, is_published) VALUES ('p-ghe-an-nordic', 'ghe-an-nordic', 'Ghế ăn Nordic', 'ban-ghe', 2900000, 'Những đường cong mộc mạc, dành cho góc sum vầy mỗi ngày.', 'Ghế ăn Nordic mang dáng vẻ thanh thoát với phần tựa lưng cong và mặt ngồi đan. Một gợi ý cho bàn ăn ấm cúng, góc đọc sách hoặc không gian bạn muốn dành thêm một chỗ ngồi.', '[{"src":"/images/Ghe/Ghe-an-Nordic/ghe-an-nordic.webp","thumbnail":"/images/Ghe/Ghe-an-Nordic/ghe-an-nordic-600.webp","alt":"Ghế ăn Nordic có tựa lưng cong và mặt ngồi đan bên rèm cửa","width":1200,"height":896},{"src":"/images/Ghe/Ghe-an-Nordic/ghe-an-nordic-gan.webp","thumbnail":"/images/Ghe/Ghe-an-Nordic/ghe-an-nordic-gan-600.webp","alt":"Cận cảnh tựa lưng và mặt ngồi đan của Ghế ăn Nordic","width":1024,"height":764}]'::jsonb, '[{"label":"Chất liệu","value":null},{"label":"Kích thước","value":null},{"label":"Màu sắc","value":null}]'::jsonb, 2, true, true);
INSERT INTO luma.products (id, slug, name, category_id, price_vnd, short_description, description, images, specifications, display_order, is_featured, is_published) VALUES ('p-den-ban-horizon', 'den-ban-horizon', 'Đèn bàn Horizon', 'den', 1250000, 'Một quầng sáng ấm cho những khoảng lặng trong ngày.', 'Dáng vòm nhẹ nhàng và ánh sáng ấm tạo điểm nhấn cho chiếc tủ, góc làm việc hoặc bàn bên cạnh sofa. Đèn bàn Horizon gợi nên một không gian thư thái khi ngày dần khép lại.', '[{"src":"/images/Den/Den-ban-Horizon/den-ban-horizon.webp","thumbnail":"/images/Den/Den-ban-Horizon/den-ban-horizon-600.webp","alt":"Đèn bàn Horizon dáng vòm với ánh sáng ấm trên mặt tủ","width":1200,"height":896}]'::jsonb, '[{"label":"Chất liệu","value":null},{"label":"Kích thước","value":null},{"label":"Màu sắc","value":null}]'::jsonb, 3, true, true);
INSERT INTO luma.products (id, slug, name, category_id, price_vnd, short_description, description, images, specifications, display_order, is_featured, is_published) VALUES ('p-bo-coc-gom-moc', 'bo-coc-gom-moc', 'Bộ cốc Gốm Mộc', 'gom-su', 450000, 'Chậm lại một chút, bên thức uống bạn yêu thích.', 'Sắc gốm trung tính với những chấm màu tự nhiên tạo cảm giác gần gũi trên bàn trà. Bộ cốc Gốm Mộc là gợi ý nhỏ cho những buổi sáng thong thả và phút nghỉ giữa ngày.', '[{"src":"/images/Gom-su/Bo-coc-Gom-Moc/bo-coc-gom-moc.webp","thumbnail":"/images/Gom-su/Bo-coc-Gom-Moc/bo-coc-gom-moc-600.webp","alt":"Hai cốc Gốm Mộc đặt trên khay gỗ cạnh tấm vải sáng màu","width":1200,"height":896}]'::jsonb, '[{"label":"Chất liệu","value":null},{"label":"Kích thước","value":null},{"label":"Màu sắc","value":null}]'::jsonb, 4, true, true);
INSERT INTO luma.home_content (id, content, is_published) VALUES ('home', '{"heroTitle":"Những món đồ nhỏ làm nên tổ ấm lớn","heroDescription":"Nội thất và gia dụng tinh giản, mang cảm hứng đến những không gian sống trọn vẹn hơn mỗi ngày.","heroImage":{"src":"/images/Khong-gian/Phong-khach-Nordic/phong-khach-nordic.webp","thumbnail":"/images/Khong-gian/Phong-khach-Nordic/phong-khach-nordic-600.webp","alt":"Phòng khách với sofa sáng màu, bàn tròn và ánh nắng qua rèm cửa","width":1200,"height":896},"featuredProductIds":["p-binh-gom-luma","p-ghe-an-nordic","p-den-ban-horizon","p-bo-coc-gom-moc"],"spaces":[{"title":"Phòng khách Ánh Nắng & Linen","description":"Một khoảng dừng dịu dàng giữa nhịp sống.","image":{"src":"/images/Khong-gian/Phong-khach-Nordic/phong-khach-nordic.webp","thumbnail":"/images/Khong-gian/Phong-khach-Nordic/phong-khach-nordic-600.webp","alt":"Không gian phòng khách với sofa và bàn trà","width":1200,"height":896},"href":"/san-pham"},{"title":"Phòng ăn Gỗ Sồi Japandi","description":"Nơi những câu chuyện được sẻ chia.","image":{"src":"/images/Khong-gian/Phong-an-Japandi/phong-an-japandi.webp","thumbnail":"/images/Khong-gian/Phong-an-Japandi/phong-an-japandi-600.webp","alt":"Không gian phòng ăn với bàn và ghế sáng màu","width":1200,"height":896},"href":"/san-pham?category=ban-ghe"}]}'::jsonb, true);
